/*
 * A362468  Number of distinct n-digit suffixes generated by iteratively
 *          multiplying an integer by 4, where the initial integer is 1.
 * https://oeis.org/A362468
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = ceil(n/2) + 2*5^(n-1)
 * Range:     u8 n <= 4, u16 n <= 7, u32 n <= 14, u64 n <= 28, u128 n <= 55,
 *            big any n
 * Helpers:   power5
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  a satisfies the recurrence: a(n) = 6*a(n-1) - 4*a(n-2) - 6*a(n-3) + 5*a(n-4),  n>4 */

/* pow5 is provided by the library */
#include "../utils/power5.h"

seq_t a(idx_t n) {
    /* transient part: t = ceil(n/2) = (n+1)/2 for integer n>=1 */
    seq_t t = ((seq_t)n + 1) / 2;
    /* period part: k = 2 * 5^(n-1) */
    seq_t k = 2 * power5(n - 1);
    return t + k;
}
